   309→                                        let result = match block_or_sidecar {
   310→                                            BlockOrDataColumnSidecar::Block(block) => eip_7594::construct_data_column_sidecars(
   311→                                                &block,
   312→                                                &cells_and_kzg_proofs,
   313→                                            ),
