    97→pub fn compute_columns_for_custody_group<P: Preset>(
    98→    custody_group: CustodyIndex,
    99→    config: &Config,
   100→) -> Result<impl Iterator<Item = ColumnIndex>> {
   101→    let number_of_custody_groups = config.number_of_custody_groups;
   102→    ensure!(
   103→        custody_group < number_of_custody_groups,
   104→        Error::InvalidCustodyGroup {
   105→            custody_group,
   106→            number_of_custody_groups,
   107→        },
   108→    );
   109→
   110→    let mut columns = Vec::new();
   111→    for i in 0..config.columns_per_group::<P>() {
   112→        columns.push(ColumnIndex::from(
   113→            number_of_custody_groups * i + custody_group,
   114→        ));
   115→    }
   116→
   117→    Ok(columns.into_iter())
   118→}
