   293→pub fn construct_data_column_sidecars<P: Preset>(
   294→    signed_block: &SignedBeaconBlock<P>,
   295→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   296→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   297→    let signed_block_header = signed_block.to_header();
   298→    let Some(post_electra_beacon_block_body) = signed_block.message().body().post_electra() else {
   299→        return Ok(vec![]);
   300→    };
   301→
   302→    let kzg_commitments = post_electra_beacon_block_body.blob_kzg_commitments();
   303→    if kzg_commitments.is_empty() {
   304→        return Ok(vec![]);
   305→    }
   306→
   307→    let kzg_commitments_inclusion_proof =
   308→        misc::kzg_commitments_inclusion_proof(post_electra_beacon_block_body);
   309→
   310→    get_data_column_sidecars(
   311→        signed_block_header,
   312→        kzg_commitments,
   313→        kzg_commitments_inclusion_proof,
   314→        cells_and_kzg_proofs,
   315→    )
   316→}
